		if msg.BodyType != "init" {
			return nil
		}
		var body struct {
			NodeID  string   `json:"node_id"`
			NodeIDs []string `json:"node_ids"`
		}
		json.Unmarshal(msg.BodyBytes, &body)

		// Initialize state with known node IDs and create a map of values
		nodeID := body.NodeID
		allNodeIDs := body.NodeIDs

		values := make(map[int64]int64) // msg_id -> value stored on this node

		// Broadcast to all nodes (including self)
		for _, destID := range allNodeIDs {
			// Send the current node's ID so others know who we are
			broadcastMsg := map[string]interface{}{
				"type":           "broadcast",
				"msg_id":         msg.MsgID, // Using this for identification
				"src_node_id":    nodeID,
				"value_source_id": msg.MsgID, // Identify where the value came from
			}
			broadcastBytes, _ := json.Marshal(broadcastMsg)
			go.Node.Send(destID, broadcastBytes)

			topologyMsg := map[string]interface{}{
				"type":     "topology",
				"msg_id":   msg.MsgID,
				"src_node": nodeID,
				"all_nodes": allNodeIDs,
			}
			topologyBytes, _ := json.Marshal(topologyMsg)
			go.Node.Send(destID, topologyBytes)

			readTopologyMsg := map[string]interface{}{
				"type":       "read",
				"msg_id":     msg.MsgID,
				"src_node_id": nodeID,
			}
			readTopBytes, _ := json.Marshal(readTopologyMsg)
			go.Node.Send(destID, readTopBytes)
		}

		initReply := map[string]interface{}{
			"type":           "init_ok",
			"in_reply_to":    0, // Placeholder
			"node_id":        nodeID,
			"all_node_ids":   allNodeIDs,
			"value_source_id": msg.MsgID,
		}
		initReplyBytes, _ := json.Marshal(initReply)
		return go.Node.Reply(msg, initReplyBytes)
	})

	// Handle topology message - store topology info for future use
	node.Handle(func(msg go.Message) error {
		if msg.BodyType != "topology" {
			return nil
		}

		var body struct {
			AllNodes []string `json:"all_nodes"`
		}
		json.Unmarshal(msg.BodyBytes, &body)

		topologyOK := map[string]interface{}{
			"type":          "topology_ok",
			"in_reply_to":   msg.MsgID,
			"my_id":         go.Node.ID(),
			"all_node_ids":  body.AllNodes,
		}
		topReplyBytes, _ := json.Marshal(topologyOK)
		return go.Node.Reply(msg, topReplyBytes)
	})

	// Handle broadcast message - acknowledge and store the value
	node.Handle(func(msg go.Message) error {
		if msg.BodyType != "broadcast" {
			return nil
		}

		var body struct {
			ValueSourceID int64 `json:"value_source_id"`
			Value          int64 `json:"message"` // The value being broadcasted
			FromNode       string `json:"src_node_id"`
		}
