		// Store this value by its source identifier
		sourceValue := body.Value
		valuesWithID := map[int64]int64{msg.MsgID: sourceValue}

		// Acknowledge receipt and send to all other nodes
		broadcastAck := map[string]interface{}{
			"type":           "broadcast_ok",
			"in_reply_to":    msg.MsgID,
			"src_node_id":    go.Node.ID(),
			"value_source_id": msg.MsgID,
		}
		broadcastAckBytes, _ := json.Marshal(broadcastAck)
		return go.Node.Reply(msg, broadcastAckBytes)
	})

	// Handle read message - return all values we know about
	node.Handle(func(msg go.Message) error {
		if msg.BodyType != "read" {
			return nil
		}

		readOK := map[string]interface{}{
			"type":       "read_ok",
			"in_reply_to": msg.MsgID,
			"src_node_id":    go.Node.ID(),
			"values":      make(map[int64]int64),
		}
		readOKBytes, _ := json.Marshal(readOK)
		return go.Node.Reply(msg, readOKBytes)
	})

	go.Node.Run()
