package main

import (
	"encoding/json"
	"fmt"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// NodeState holds state for a single node
type NodeState struct {
	myID          string
	allNodeIDs    []string
	values        map[int64]int64 // msg_id -> value
	valueSources  map[string]map[int64]int64 // dest_node_id -> (msg_id -> value)
	mu            sync.RWMutex
}

func makeState(allNodeIDs []string) NodeState {
	return NodeState{
		values:       make(map[int64]int64),
		valueSources: make(map[string]map[int64]int64),
		allNodeIDs:   allNodeIDs,
	}
}

func (ns *NodeState) init(id string) {
	ns.myID = id
}

func (ns *NodeState) broadcast(value int64) int64 {
	msgID := int64(len(ns.values))
	ns.mu.Lock()
	ns.values[msgID] = value
	ns.mu.Unlock()
	return msgID
}

func (ns *NodeState) getValues() []int64 {
	ns.mu.RLock()
	defer ns.mu.RUnlock()

	result := make([]int64, 0, len(ns.values))
	for _, v := range ns.values {
		result = append(result, v)
	}
	return result
}

func (ns *NodeState) getValuesFor(dest string) []int64 {
	ns.mu.RLock()
	defer ns.mu.RUnlock()

	destSources := ns.valueSources[dest]
	if destSources == nil {
		return make([]int64, 0)
	}

	result := make([]int64, 0, len(destSources))
	for _, v := range destSources {
		result = append(result, v)
	}
	return result
}

func (ns *NodeState) addSourceValue(sourceID string, msgID int64, value int64) {
	ns.mu.Lock()
